const linhas = $input.all().map((i) => i.json);

// campanhas_complementares vazia -> a query nem devolve linha (nem o
// "cabeçalho" da campanha) -- sem período configurado, não tem o que
// mandar.
if (linhas.length === 0) {
  return [];
}

const campanha = linhas[0];
const ranking = linhas.filter((l) => l.nome_vendedor != null);

const hojeLabel = new Date().toLocaleDateString('pt-BR', { timeZone: 'America/Sao_Paulo' });
const MEDALHAS = { 1: '🥇', 2: '🥈', 3: '🥉' };

function fmtBRL(v) {
  return (Number(v) || 0).toLocaleString('pt-BR', { style: 'currency', currency: 'BRL' });
}
// O nó Postgres pode devolver coluna "date" como objeto Date do JS OU
// como string ISO completa (com hora/timezone), não como "YYYY-MM-DD"
// puro — grudar "T00:00:00" na string quebrava o parse ("Invalid
// Date"/"NaN"). new Date(valor) lida com objeto Date, string curta ou
// ISO completa igual; os getters UTC evitam rolar pro dia anterior por
// fuso, já que "date" não tem hora nenhuma.
function fmtData(valor) {
  const data = new Date(valor);
  const dia = String(data.getUTCDate()).padStart(2, '0');
  const mes = String(data.getUTCMonth() + 1).padStart(2, '0');
  return `${dia}/${mes}/${data.getUTCFullYear()}`;
}

const partes = [`🏆 *Ranking Vendas Complementares*`, `📅 ${hojeLabel}`, ''];

if (ranking.length === 0) {
  partes.push('Ninguém bateu a meta ainda hoje.');
} else {
  for (const item of ranking) {
    const rotulo = MEDALHAS[item.posicao] ?? `${item.posicao}º`;
    const qtdTexto = `${item.quantidade_total} ${Number(item.quantidade_total) === 1 ? 'item' : 'itens'}`;
    if (item.premio != null) {
      partes.push(`${rotulo} ${item.nome_vendedor} — ${fmtBRL(item.valor_total)} · ${qtdTexto} (prêmio ${fmtBRL(item.premio)})`);
    } else {
      partes.push(`${rotulo} ${item.nome_vendedor} — ${fmtBRL(item.valor_total)} · ${qtdTexto} ✅ bateu a meta`);
    }
  }
}

const metas = [];
if (campanha.valor_minimo) metas.push(fmtBRL(campanha.valor_minimo));
if (campanha.quantidade_minima) metas.push(`${campanha.quantidade_minima} itens`);
partes.push('');
partes.push(`Meta pra concorrer: ${metas.length > 0 ? metas.join(' e ') : 'sem piso mínimo'}`);
partes.push(`Período: ${fmtData(campanha.data_inicio)} a ${fmtData(campanha.data_fim)}`);

return [{ json: { mensagem: partes.join('\n') } }];
